<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { ArrowLeft, BookOpen, Castle, CheckCircle2, Clock3, Crown, Gem, Heart, KeyRound, LogOut, Plus, RefreshCw, ShieldAlert, Skull, Sparkles, Swords, Users } from 'lucide-vue-next'
import { isSupabaseConfigured, requireSupabase } from '../services/supabase'
import { createAdventure, joinAdventure, startAdventure, submitAdventureAnswer, claimAdventureTreasure, sendAdventureHeartbeat, teacherAction, loadAdventurePlayers, loadAdventureEvents, loadAdventureInventory, subscribeAdventure, removeAdventureSubscription } from '../modules/adventure/adventureService'
import type { AdventureDifficulty, AdventureGame, AdventureChallenge, AdventurePlayer, AdventureEvent, AdventureInventoryItem } from '../modules/adventure/types'

const role=ref<'teacher'|'player'>('player')
const title=ref('Las catacumbas de la guitarra'),difficulty=ref<AdventureDifficulty>('beginner')
const code=ref(''),nickname=ref(''),game=ref<AdventureGame|null>(null),playerId=ref('')
const challenge=ref<AdventureChallenge|null>(null),roomIndex=ref(0),errors=ref(0),eliminated=ref(false),completed=ref(false)
const players=ref<AdventurePlayer[]>([]),events=ref<AdventureEvent[]>([]),inventory=ref<AdventureInventoryItem[]>([])
const selected=ref(''),busy=ref(false),message=ref(''),announcement=ref('')
const teacherGift=ref('Poción de vida'),giftTarget=ref(''),eventText=ref('')
let channel:any=null,heartbeat:ReturnType<typeof setInterval>|undefined,refreshTimer:ReturnType<typeof setInterval>|undefined
const isTeacher=computed(()=>role.value==='teacher')
const roomNames=['La puerta de las notas','El corredor de Sol mayor','La cámara de Do mayor','La sala de Mi mayor','El puente de los acordes','El tesoro de las catacumbas']
const roomProgress=computed(()=>Math.min(roomIndex.value,5))
const gameCode=computed(()=>game.value?.code??code.value.toUpperCase())
function difficultyName(v:AdventureDifficulty){return ({beginner:'Principiante',intermediate:'Intermedio',advanced:'Avanzado',mixed:'Mixto'} as const)[v]}
async function refresh(){
 if(!game.value)return
 try{players.value=await loadAdventurePlayers(game.value.id);events.value=await loadAdventureEvents(game.value.id);if(playerId.value)inventory.value=await loadAdventureInventory(playerId.value)
 const {data}=await requireSupabase().from('adventure_games').select('id,code,title,status,difficulty,created_at').eq('id',game.value.id).single();if(data)game.value=data as AdventureGame
 const mine=players.value.find(p=>p.id===playerId.value);if(mine){roomIndex.value=mine.room_index;errors.value=mine.errors;eliminated.value=mine.eliminated;completed.value=Boolean(mine.finished_at)}
 }catch(e){message.value=e instanceof Error?e.message:'No se pudo actualizar la partida.'}
}
function listen(){if(!game.value)return;if(channel)removeAdventureSubscription(channel);channel=subscribeAdventure(game.value.id,()=>void refresh());if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>void refresh(),12000)}
async function createGame(){busy.value=true;message.value='';try{const {data:s}=await requireSupabase().auth.getSession();if(!s.session)throw new Error('Inicia sesión como docente antes de crear una partida.');game.value=await createAdventure(title.value,difficulty.value);role.value='teacher';await refresh();listen();message.value='Partida creada. Comparte el código con tus estudiantes.'}catch(e){message.value=e instanceof Error?e.message:'No se pudo crear la partida.'}finally{busy.value=false}}
async function joinGame(){busy.value=true;message.value='';try{const db=requireSupabase();const {data:s}=await db.auth.getSession();if(!s.session){const {error}=await db.auth.signInAnonymously();if(error)throw error}const result=await joinAdventure(code.value,nickname.value);game.value=result.game;playerId.value=result.player_id;challenge.value=result.challenge;roomIndex.value=result.room_index;errors.value=result.errors;eliminated.value=result.eliminated;role.value='player';await refresh();listen();heartbeat=setInterval(()=>{if(game.value)void sendAdventureHeartbeat(game.value.id).catch(()=>{})},45000)}catch(e){message.value=e instanceof Error?e.message:'No se pudo ingresar a la aventura.'}finally{busy.value=false}}
async function begin(){if(!game.value)return;busy.value=true;try{await startAdventure(game.value.id);await refresh();message.value='¡Las catacumbas se han abierto!'}catch(e){message.value=e instanceof Error?e.message:'No se pudo iniciar la partida.'}finally{busy.value=false}}
async function answer(){if(!game.value||!selected.value)return;busy.value=true;message.value='';try{const result=await submitAdventureAnswer(game.value.id,selected.value);challenge.value=result.challenge;roomIndex.value=result.room_index;errors.value=result.errors;eliminated.value=result.eliminated;completed.value=result.completed;message.value=result.message;selected.value='';await refresh()}catch(e){message.value=e instanceof Error?e.message:'No se pudo registrar la respuesta.'}finally{busy.value=false}}
async function claimTreasure(){if(!game.value)return;busy.value=true;try{const r=await claimAdventureTreasure(game.value.id);message.value=r.message;await refresh()}catch(e){message.value=e instanceof Error?e.message:'No se pudo reclamar el tesoro.'}finally{busy.value=false}}
async function action(name:string,payload:Record<string,unknown>={}){if(!game.value)return;busy.value=true;try{await teacherAction(game.value.id,name,payload);await refresh();message.value='Acción del maestro del juego ejecutada.'}catch(e){message.value=e instanceof Error?e.message:'No se pudo ejecutar la acción.'}finally{busy.value=false}}
async function announce(){if(!eventText.value.trim())return;await action('announce',{message:eventText.value.trim()});eventText.value=''}
async function giveGift(){if(!giftTarget.value)return;await action('gift',{player_id:giftTarget.value,item_key:'teacher_gift',label:teacherGift.value,description:'Regalo entregado por el maestro del juego'});giftTarget.value=''}
async function logout(){if(channel)removeAdventureSubscription(channel);channel=null;if(heartbeat)clearInterval(heartbeat);if(refreshTimer)clearInterval(refreshTimer);game.value=null;playerId.value='';challenge.value=null;players.value=[];events.value=[];inventory.value=[];message.value='Has salido de la vista de partida.'}
onMounted(()=>{if(!isSupabaseConfigured)message.value='Conecta Supabase para habilitar las partidas compartidas.'})
onUnmounted(()=>{if(channel)removeAdventureSubscription(channel);if(heartbeat)clearInterval(heartbeat);if(refreshTimer)clearInterval(refreshTimer)})
</script>
<template>
<div class="page">
 <div class="mb-6 flex items-center gap-3"><RouterLink to="/" class="secondary"><ArrowLeft :size="17"/></RouterLink><div><p class="eyebrow">Modo aventura · multijugador</p><h1 class="text-2xl font-black sm:text-3xl">Catacumbas de la Guitarra</h1></div></div>
 <section v-if="!isSupabaseConfigured" class="panel p-6"><h2 class="text-xl font-black">Aventura en preparación</h2><p class="mt-2 text-sm text-[#718078]">La partida compartida necesita Supabase y la migración de aventura.</p></section>
 <template v-else-if="!game">
  <section class="panel mx-auto max-w-3xl p-5 sm:p-7">
   <div class="flex flex-wrap items-center justify-between gap-3"><div><p class="eyebrow">Elige tu acceso</p><h2 class="mt-1 text-xl font-black">Una aventura musical para toda la clase</h2></div><div class="flex rounded-xl bg-[#eef3ef] p-1"><button class="rounded-lg px-3 py-2 text-sm font-bold" :class="role==='player'?'bg-white shadow-sm':''" @click="role='player'">Estudiante</button><button class="rounded-lg px-3 py-2 text-sm font-bold" :class="role==='teacher'?'bg-white shadow-sm':''" @click="role='teacher'">Docente</button></div></div>
   <div class="mt-5 grid gap-4 sm:grid-cols-2">
    <form v-if="role==='player'" class="rounded-2xl bg-[#f5f8f5] p-5" @submit.prevent="joinGame"><div class="grid h-11 w-11 place-items-center rounded-xl bg-[#e5f0e8] text-[#26745a]"><KeyRound/></div><h3 class="mt-3 font-extrabold">Entrar a las catacumbas</h3><label class="mt-4 block text-sm font-bold">Código de partida</label><input v-model="code" required maxlength="8" class="mt-1 w-full rounded-xl border border-[#dce6dd] px-3 py-3 uppercase tracking-widest" placeholder="ABC123"/><label class="mt-3 block text-sm font-bold">Nombre de aventurero</label><input v-model="nickname" required maxlength="24" class="mt-1 w-full rounded-xl border border-[#dce6dd] px-3 py-3" placeholder="Tu nombre o apodo"/><button class="primary mt-4 w-full justify-center" :disabled="busy">Entrar en la aventura</button></form>
    <form v-else class="rounded-2xl bg-[#f5f8f5] p-5" @submit.prevent="createGame"><div class="grid h-11 w-11 place-items-center rounded-xl bg-[#e5f0e8] text-[#26745a]"><Crown/></div><h3 class="mt-3 font-extrabold">Crear una partida</h3><label class="mt-4 block text-sm font-bold">Nombre de la aventura</label><input v-model="title" required maxlength="90" class="mt-1 w-full rounded-xl border border-[#dce6dd] px-3 py-3"/><label class="mt-3 block text-sm font-bold">Dificultad</label><select v-model="difficulty" class="mt-1 w-full rounded-xl border border-[#dce6dd] bg-white px-3 py-3"><option value="beginner">Principiante</option><option value="intermediate">Intermedio</option><option value="advanced">Avanzado</option><option value="mixed">Mixto</option></select><button class="primary mt-4 w-full justify-center" :disabled="busy"><Plus :size="17"/>Crear partida</button></form>
    <div class="rounded-2xl bg-[#173f36] p-5 text-white"><Castle :size="30" class="text-[#a6d6bf]"/><h3 class="mt-3 font-extrabold">Seis estancias misteriosas</h3><p class="mt-2 text-sm leading-6 text-[#d3e3da]">Cinco salas de retos musicales y una cámara final del tesoro. Cada estudiante avanza a su propio ritmo.</p><div class="mt-4 flex gap-2 text-xs font-bold text-[#b8dec7]"><Heart :size="15"/> Tres errores y quedas fuera de la expedición.</div></div>
   </div><p v-if="message" class="mt-4 rounded-xl bg-[#f0f5f0] p-3 text-sm text-[#37644f]">{{message}}</p>
  </section>
 </template>
 <template v-else>
  <section class="panel mb-4 flex flex-wrap items-center justify-between gap-3 p-4"><div><p class="eyebrow">{{game.status==='lobby'?'Sala de espera':game.status==='active'?'Aventura en curso':'Partida finalizada'}}</p><h2 class="text-lg font-black">{{game.title}}</h2><p class="text-xs text-[#718078]">Código: <b class="tracking-widest">{{game.code}}</b> · {{difficultyName(game.difficulty)}}</p></div><div class="flex gap-2"><button class="secondary" @click="refresh"><RefreshCw :size="16"/></button><button class="secondary" @click="logout"><LogOut :size="16"/> Salir</button></div></section>
  <div class="grid gap-4 lg:grid-cols-[1fr_300px]">
   <div class="space-y-4">
    <section class="panel p-5 sm:p-6"><div class="flex items-center justify-between gap-3"><div><p class="eyebrow">Tu recorrido</p><h3 class="text-xl font-black">{{challenge?.room_title??roomNames[Math.min(roomIndex,5)]}}</h3></div><span class="rounded-full bg-[#edf4ee] px-3 py-1.5 text-xs font-bold text-[#34745b]">Sala {{Math.min(roomIndex+1,6)}} / 6</span></div><div class="mt-4 flex gap-1.5">{#each roomNames as name,i}<div class="h-2 flex-1 rounded-full" :class="i<roomIndex?'bg-[#398568]':i===roomIndex?'bg-[#b6d9c1]':'bg-[#e7ece7]'"/></div>
     <div v-if="role==='teacher'" class="mt-5 rounded-xl bg-[#edf4ee] p-4"><p class="text-sm font-bold text-[#28684f]">Panel del maestro del juego</p><p class="mt-1 text-xs text-[#718078]">La partida se controla desde aquí. Los estudiantes avanzan individualmente.</p><button v-if="game.status==='lobby'" class="primary mt-3" :disabled="busy" @click="begin">Abrir las catacumbas</button><div class="mt-4 grid gap-2 sm:grid-cols-2"><button class="secondary justify-center" @click="action('spawn_treasure')"><Gem :size="15"/> Aparecer tesoro</button><button class="secondary justify-center" @click="action('summon_enemy')"><Swords :size="15"/> Invocar enemigo</button><button class="secondary justify-center" @click="action('revive',{player_id:giftTarget})"><Heart :size="15"/> Revivir seleccionado</button><button class="secondary justify-center" @click="action('remove_item',{player_id:giftTarget,item_key:'teacher_gift'})"><ShieldAlert :size="15"/> Retirar regalo</button></div><label class="mt-3 block text-xs font-bold">Estudiante objetivo</label><select v-model="giftTarget" class="mt-1 w-full rounded-xl border border-[#dce6dd] bg-white px-3 py-2 text-sm"><option value="">Seleccionar estudiante</option><option v-for="p in players" :key="p.id" :value="p.id">{{p.nickname}}</option></select><div class="mt-3 flex gap-2"><input v-model="eventText" class="min-w-0 flex-1 rounded-xl border border-[#dce6dd] px-3 py-2 text-sm" placeholder="Anuncio para el grupo"/><button class="secondary" @click="announce">Anunciar</button></div><div class="mt-3 flex gap-2"><input v-model="teacherGift" class="min-w-0 flex-1 rounded-xl border border-[#dce6dd] px-3 py-2 text-sm" placeholder="Nombre del regalo"/><button class="secondary" @click="giveGift">Entregar regalo</button></div><button class="mt-3 rounded-xl bg-[#8e3e36] px-4 py-2 text-sm font-bold text-white" @click="action('end_game')">Finalizar partida</button></div>
     <div v-else-if="game.status==='lobby'" class="py-8 text-center"><Clock3 class="mx-auto text-[#7c9185]" :size="34"/><h3 class="mt-3 font-bold">Esperando al maestro del juego</h3><p class="mt-1 text-sm text-[#718078]">Cuando comience la partida aparecerá tu primer desafío.</p></div>
     <div v-else-if="eliminated" class="py-8 text-center"><Skull class="mx-auto text-[#9b4f3c]" :size="40"/><h3 class="mt-3 text-xl font-black">Has quedado fuera de la expedición</h3><p class="mt-2 text-sm text-[#718078]">Puedes seguir observando el recorrido de tus compañeros. El docente puede concederte una nueva oportunidad.</p></div>
     <div v-else-if="completed||roomIndex>=5" class="py-8 text-center"><Gem class="mx-auto text-[#b58a3a]" :size="42"/><h3 class="mt-3 text-2xl font-black">¡Has llegado a la cámara del tesoro!</h3><p class="mt-2 text-sm text-[#718078]">El tesoro es compartido: el primer aventurero que lo reclame lo obtiene.</p><button class="primary mt-4" :disabled="busy" @click="claimTreasure">Reclamar tesoro</button></div>
     <div v-else-if="challenge" class="mt-5"><p class="text-sm text-[#718078]">{{challenge.room_description}}</p><div class="mt-4 rounded-2xl border border-[#e6ebe5] bg-[#fbfcfa] p-5"><p class="eyebrow">Acertijo musical</p><h4 class="mt-2 text-lg font-black">{{challenge.prompt}}</h4><div class="mt-4 grid gap-2 sm:grid-cols-2"><button v-for="(option,i) in challenge.options" :key="option" class="rounded-xl border p-3 text-left text-sm font-bold" :class="selected===option?'border-[#28785e] bg-[#eaf4ed] text-[#23664d]':'border-[#e1e9e2] bg-white hover:border-[#9bb9a6]'" @click="selected=option"><b class="mr-2 text-[#8a9b90]">{{String.fromCharCode(65+i)}}.</b>{{option}}</button></div><button class="primary mt-4" :disabled="!selected||busy" @click="answer">{{busy?'Comprobando…':'Abrir la siguiente puerta'}}</button></div><p class="mt-3 flex items-center gap-2 text-sm text-[#718078]"><Heart :size="16" class="text-[#a85a52]"/> Errores: <b>{{errors}} / 3</b></p></div>
     <div v-else class="py-8 text-center text-sm text-[#718078]">Esperando el siguiente desafío…</div>
     <p v-if="message" class="mt-4 rounded-xl bg-[#f0f5f0] p-3 text-sm text-[#37644f]" aria-live="polite">{{message}}</p>
    </section>
   </div>
   <aside class="space-y-4"><section class="panel p-4"><div class="flex items-center gap-2"><Users class="text-[#398568]"/><h3 class="font-extrabold">Expedición</h3><span class="ml-auto text-xs text-[#718078]">{{players.length}}</span></div><div class="mt-3 space-y-2"><div v-for="p in players" :key="p.id" class="flex items-center gap-2 rounded-xl bg-[#f5f8f5] p-2.5"><span class="grid h-8 w-8 place-items-center rounded-lg bg-[#e5f0e8] text-xs font-black text-[#34745b]">{{p.nickname.slice(0,1).toUpperCase()}}</span><div class="min-w-0 flex-1"><p class="truncate text-sm font-bold">{{p.nickname}}</p><p class="text-[11px] text-[#718078]">{{p.eliminated?'Eliminado':p.finished_at?'Completó':'Sala '+(p.room_index+1)}} · {{p.errors}} errores</p></div><Skull v-if="p.eliminated" :size="16" class="text-[#a85a52]"/></div></div></section>
    <section v-if="role==='player'" class="panel p-4"><div class="flex items-center gap-2"><BookOpen class="text-[#398568]"/><h3 class="font-extrabold">Mi inventario</h3></div><p v-if="!inventory.length" class="mt-2 text-xs text-[#718078]">Todavía no tienes objetos. El docente puede entregarte regalos.</p><div v-for="item in inventory" :key="item.id" class="mt-2 rounded-xl bg-[#f5f8f5] p-3"><p class="text-sm font-bold">{{item.label}} <span class="text-xs text-[#718078]">×{{item.quantity}}</span></p><p class="mt-1 text-xs text-[#718078]">{{item.description}}</p></div></section>
    <section class="panel p-4"><div class="flex items-center gap-2"><Sparkles class="text-[#398568]"/><h3 class="font-extrabold">Bitácora</h3></div><div class="mt-3 space-y-3"><div v-for="event in events.slice(0,8)" :key="event.id" class="border-l-2 border-[#b6d9c1] pl-3"><p class="text-xs">{{event.message}}</p><p class="mt-1 text-[10px] text-[#8a9890]">{{new Date(event.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}}</p></div><p v-if="!events.length" class="text-xs text-[#718078]">Aún no hay eventos.</p></div></section>
   </aside>
  </div>
 </template>
</div>
</template>
